-- Token-refresh lease (replaces holding a row lock across the call to Shopify).
-- Claimed and released with single conditional UPDATEs; both columns are nullable,
-- so this is safe on an existing database.

-- AlterTable (generated by `prisma migrate diff`)
ALTER TABLE "integration_connections" ADD COLUMN     "refresh_lease_id" TEXT,
ADD COLUMN     "refresh_lease_until" TIMESTAMP(3);
